});

test("llm_task.invoke uses CLAWD_URL (/tools/invoke) without requiring --url/--model", async () => {
	const registry = createDefaultRegistry();
	const cmd = registry.get("llm_task.invoke");
	assert.ok(cmd);

	const cacheDir = await mkdtemp(path.join(tmpdir(), "lobster-cache-"));

	const bodyLog: any[] = [];
	const server = http.createServer((req, res) => {
		if (req.method !== "POST" || req.url !== "/tools/invoke") {
			res.writeHead(404);
			res.end("not found");
			return;
		}

		let buf = "";
		req.setEncoding("utf8");
		req.on("data", (d) => (buf += d));
		req.on("end", () => {
			const parsed = JSON.parse(buf || "{}");
			bodyLog.push(parsed);

			// This is the OpenClaw tool router envelope.
			res.writeHead(200, { "content-type": "application/json" });
			res.end(JSON.stringify(gatewayResult({ hello: "world" })));
		});
	});

	await new Promise<void>((resolve) => server.listen(0, resolve));
	const addr = server.address();
	const port = typeof addr === "object" && addr ? addr.port : 0;

	try {
		const result = await cmd.run({
			input: streamOf([{ kind: "text", text: "doc" }]),
			args: {
				_: [],
				// no url, no model
				prompt: "Summarize",
				refresh: true,
			},
			ctx: baseCtx(
				{ CLAWD_URL: `http://localhost:${port}`, LOBSTER_CACHE_DIR: cacheDir },
				registry,
			),
		} as any);

		const items = await collect(result.output!);
		assert.equal(items.length, 1);
		assert.equal(items[0].source, "clawd");
		assert.equal(items[0].cached, false);
		assert.equal(items[0].runId, null);
		assert.equal(items[0].output.data.hello, "world");

		assert.equal(bodyLog.length, 1);
		assert.equal(bodyLog[0].tool, "llm-task");
		assert.equal(bodyLog[0].action, "invoke");
		assert.equal(bodyLog[0].args.prompt, "Summarize");
		assert.ok(Array.isArray(bodyLog[0].args.input));
	} finally {
		await rm(cacheDir, { recursive: true, force: true });
		await closeServer(server);
	}
});

function gatewayResult(json: unknown, model?: string) {
	return {
		ok: true,
		result: {
			content: [{ type: "text", text: JSON.stringify(json) }],
			details: { json, ...(model ? { model } : {}) },
		},
	};
}

function baseCtx(envOverrides: Record<string, string>, registry?) {
	return {
		stdin: process.stdin,
		stdout: process.stdout,
		stderr: process.stderr,
		env: { ...process.env, ...envOverrides },
		registry: registry ?? null,
		mode: "tool",
		render: { json() {}, lines() {} },
	};
}

async function closeServer(server: http.Server) {
	if (!server.listening) return;
	await new Promise<void>((resolve) => server.close(() => resolve()));
}

import test from "node:test";
import assert from "node:assert/strict";
import http from "node:http";
import { mkdtemp, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import path from "node:path";
import { createDefaultRegistry } from "../src/commands/registry.js";

async function gateway(t, respond) {
	const requests = [];
	const cacheDir = await mkdtemp(path.join(tmpdir(), "lobster-gateway-"));
	t.after(() => rm(cacheDir, { recursive: true, force: true }));
	const server = http.createServer(async (req, res) => {
		let body = "";
		for await (const chunk of req) body += chunk;
		requests.push(JSON.parse(body));
		res.setHeader("content-type", "application/json");
		res.end(JSON.stringify(respond(requests.length)));
	});
	await new Promise<void>((resolve) => server.listen(0, "127.0.0.1", resolve));
	t.after(() => new Promise<void>((resolve) => server.close(() => resolve())));
	const address = server.address();
	assert.ok(address && typeof address === "object");
	const registry = createDefaultRegistry();
	return {
		requests,
		async run(name = "llm.invoke", args = {}) {
			const command = registry.get(name)!;
			const result = await command.run({
				input: [{ kind: "text", text: "evidence" }],
				args: { _: [], prompt: "Summarize", ...args },
				ctx: {
					env: { OPENCLAW_URL: `http://127.0.0.1:${address.port}`, LOBSTER_CACHE_DIR: cacheDir },
					registry,
				},
			} as any);
			const items = [];
			for await (const item of result.output!) items.push(item);
			return items;
		},
	};
}

function toolResult(json: unknown) {
	return {
		ok: true,
		result: {
			content: [{ type: "text", text: JSON.stringify(json, null, 2) }],
			details: { json, provider: "test-provider", model: "test-model" },
		},
	};
}

for (const command of ["llm.invoke", "llm_task.invoke"]) {
	test(`${command} translates the OpenClaw llm-task protocol`, async (t) => {
		const { requests, run } = await gateway(t, () => toolResult({ summary: "hello" }));
		const args = { model: "test-model", temperature: 0, "max-output-tokens": 32 };
		const [item] = await run(command, args);
		assert.deepEqual(item.output.data, { summary: "hello" });
		assert.equal(item.output.format, "json");
		assert.equal(item.model, "test-model");
		assert.deepEqual(requests[0], {
			tool: "llm-task",
			action: "invoke",
			args: {
				prompt: "Summarize",
				input: [{ kind: "text", text: "evidence" }],
				model: "test-model",
